      const h = harness([SUPPRESS, text('hidden')], {failWith: DROPPED});

      await h.send();

      expect({frames: h.frames(), open: stillStreaming(h.session)}).toEqual({
        frames: ['upsert 0 user "hello"', 'skip 1', 'error SERVER_ERROR', 'stream_end'],
