  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const handle = createMessageHandler(orchestrator);

  return {
    orchestrator,
    registry,
    requests,
    executed,
    frames,
    ask: (content = 'Please notify Ada') => handle(ws, session, {type: 'user_message', content}),
